const out = String($json.output || "").toLowerCase();
const c = $("Split Cases").item.json;
const mm = c.must_mention || [];
let pass;
if (c.expected === "answer") {
  pass = mm.every(m => out.includes(String(m).toLowerCase())) && !out.includes("ticket");
} else {
  pass = out.includes("ticket");
}
return { json: { id: c.id, expected: c.expected, pass, answer: $json.output } };

const rows = $input.all().map(i => i.json);
const total = rows.length;
const passed = rows.filter(r => r.pass).length;
const g = rows.filter(r => r.expected === "answer");
const e = rows.filter(r => r.expected === "escalate");
return [{ json: {
  total,
  passed,
  accuracy_pct: Math.round(100 * passed / total),
  grounding: g.filter(r => r.pass).length + "/" + g.length,
  escalation: e.filter(r => r.pass).length + "/" + e.length,
  failures: rows.filter(r => !r.pass).map(r => r.id),
  details: rows
} }];
